function racecar(target) {
  const dp = new Array(target + 1).fill(0);
  for (let t = 1; t <= target; t++) {
    let k = 1;
    while ((1 << k) - 1 < t) {
      k++;
    }
    const full = (1 << k) - 1;
    if (full === t) {
      dp[t] = k;
      continue;
    }
    dp[t] = k + 1 + dp[full - t];
    const short = (1 << (k - 1)) - 1;
    for (let back = 0; back < k - 1; back++) {
      const returned = (1 << back) - 1;
      dp[t] = Math.min(dp[t], k + 1 + back + dp[t - short + returned]);
    }
  }
  return dp[target];
}

