function racecar(target) {
  // Breadth-first search over (position, speed) states inside a generous window.
  const low = -2 * target - 4;
  const high = 4 * target + 4;
  const seen = new Set(['0,1']);
  let frontier = [[0, 1]];
  for (let steps = 0; ; steps++) {
    const next = [];
    for (const [pos, speed] of frontier) {
      if (pos === target) return steps;
      const moves = [[pos + speed, speed * 2], [pos, speed > 0 ? -1 : 1]];
      for (const [p, v] of moves) {
        const key = p + ',' + v;
        if (p < low || p > high || seen.has(key)) continue;
        seen.add(key);
        next.push([p, v]);
      }
    }
    frontier = next;
  }
}

