function generate(rand, size) {
  if (size === 'large') {
    const pick = rand();
    if (pick < 0.2) return [10000];
    if (pick < 0.35) return [8191];
    if (pick < 0.5) return [8192];
    return [5000 + Math.floor(rand() * 5001)];
  }
  if (rand() < 0.2) {
    const power = 1 << (1 + Math.floor(rand() * 7));
    return [Math.max(1, power - 1 + Math.floor(rand() * 3) - 1)];
  }
  return [1 + Math.floor(rand() * 150)];
}
